def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = int(result.get("credit_limit", 0) or 0)

    if outcome == "declined":
        return {"action": "decline", "limit": 0}

    # Network referral rule: self_employed with requested_limit strictly above 6000
    # must be queued for review (overrides approval; decline already handled above).
    if (app.get("employment") == "self_employed"
            and int(app.get("requested_limit", 0) or 0) > 6000):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}

    # manual_review or anything else: queue for review
    return {"action": "queue_review", "limit": 0}
